src='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = [[False]*w for _ in range(h)]
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r,c)])
            seen[r][c] = True
            cells = []
            while q:
                y,x = q.popleft(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                        seen[yy][xx] = True; q.append((yy,xx))
            if len(cells) >= 2:
                objects.append((color, min(y for y,x in cells), max(y for y,x in cells), min(x for y,x in cells), max(x for y,x in cells)))
    out = [[bg]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in objects:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c] = color
    return out
'''
